const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Mount Etna location
  const etna = ee.Geometry.Point([15.00, 37.75]);
  const roi = etna.buffer(20000); // 20km buffer

  // February 23, 2021 - checking a window around 1:37 AM local time (00:37 UTC)
  const targetDate = '2021-02-23';
  const startDate = '2021-02-22';
  const endDate = '2021-02-24';

  // Try VIIRS for thermal detection (better temporal resolution)
  let viirs = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterDate(startDate, endDate)
    .filterBounds(etna);

  console.log('VIIRS Images found:', viirs.size().getInfo());

  // If no VIIRS, try MODIS Terra
  if (viirs.size().getInfo() === 0) {
    viirs = ee.ImageCollection('MODIS/006/MOD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(etna);
    console.log('MODIS Terra Images found:', viirs.size().getInfo());
  }

  // If still no data, try Sentinel-5P for SO2 (volcanic plume indicator)
  if (viirs.size().getInfo() === 0) {
    const s5p = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_SO2')
      .filterDate(startDate, endDate)
      .filterBounds(etna)
      .select('SO2_column_number_density');

    console.log('Sentinel-5P SO2 Images found:', s5p.size().getInfo());

    if (s5p.size().getInfo() === 0) {
      console.log('No satellite data found for the time period.');
      console.log('<answer>C1</answer>');
      return;
    }

    // Use SO2 data to detect plume
    const so2Image = s5p.mean();

    // Define western and eastern zones
    const westZone = ee.Geometry.Rectangle([14.90, 37.70, 15.00, 37.80]);
    const eastZone = ee.Geometry.Rectangle([15.00, 37.70, 15.10, 37.80]);

    // Calculate SO2 in each zone
    const westStats = so2Image.reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: westZone,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const eastStats = so2Image.reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: eastZone,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const westMean = westStats.SO2_column_number_density_mean;
    const westCount = westStats.SO2_column_number_density_count;
    const eastMean = eastStats.SO2_column_number_density_mean;
    const eastCount = eastStats.SO2_column_number_density_count;

    console.log('West SO2:', westMean, 'Pixels:', westCount);
    console.log('East SO2:', eastMean, 'Pixels:', eastCount);

    if (westCount === 0 && eastCount === 0) {
      console.log('No valid pixels after processing.');
      console.log('<answer>C2</answer>');
      return;
    }

    if (westMean === null || westMean === undefined) {
      console.log('Calculation failed - invalid result.');
      console.log('<answer>C3</answer>');
      return;
    }

    // Check if western plume is stronger
    if (westMean > eastMean && westMean > 0.0001) {
      console.log('Plume detected on western side.');
      console.log('<answer>A</answer>');
    } else {
      console.log('Plume not primarily on western side.');
      console.log('<answer>B</answer>');
    }
    return;
  }

  // Use thermal data from VIIRS/MODIS
  const thermalImage = viirs.mean();

  // Define western and eastern zones from volcano
  const westZone = ee.Geometry.Rectangle([14.90, 37.70, 15.00, 37.80]);
  const eastZone = ee.Geometry.Rectangle([15.00, 37.70, 15.10, 37.80]);

  const bandName = viirs.first().bandNames().getInfo()[0];

  const westStats = thermalImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: westZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const eastStats = thermalImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: eastZone,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const westCount = westStats[bandName + '_count'];
  const eastCount = eastStats[bandName + '_count'];

  if (westCount === 0 && eastCount === 0) {
    console.log('No valid pixels in analysis zones.');
    console.log('<answer>C2</answer>');
    return;
  }

  const westVal = westStats[bandName + '_mean'];
  const eastVal = eastStats[bandName + '_mean'];

  console.log('West thermal:', westVal, 'Pixels:', westCount);
  console.log('East thermal:', eastVal, 'Pixels:', eastCount);

  if (westVal === null || westVal === undefined) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (westVal > eastVal) {
    console.log('Thermal anomaly stronger on west side.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Thermal anomaly not primarily western.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

